@prefix focal-shape: <https://w3id.org/ogc/hosted/focal/transferability/shapes/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/ref-map> ;
            sh:resultMessage "artifactRef is not meaningful for an external-resource artifact: it has nothing in the annotated document to point at." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "artifactRef is not meaningful for an external-resource artifact: it has nothing in the annotated document to point at." ;
                    sh:select """
      SELECT $this WHERE {
        $this <https://w3id.org/ogc/hosted/focal/transferability/properties/artifactRef> ?ref .
        $this <https://w3id.org/ogc/hosted/focal/transferability/properties/artifactRole> ?role .
        FILTER(?role = <https://w3id.org/ogc/hosted/focal/transferability/artifact-roles/external-resource>)
      }
    """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape focal-shape:ArtifactRefOnlyForInternalRoles ;
            sh:value <file:///github/workspace/ref-map> ] .

