@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/cube> ;
            sh:resultMessage "artifactRef entries are JSON Pointers (RFC 6901) and therefore start with '/'." ;
            sh:resultPath focal-prop:artifactRef ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:PatternConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "artifactRef entries are JSON Pointers (RFC 6901) and therefore start with '/'." ;
                    sh:name "artifactRef" ;
                    sh:path focal-prop:artifactRef ;
                    sh:pattern "^/" ] ;
            sh:value "registry" ] .

